import pathlib
for i in range(12):
 counts={}
 for name in ['netstat','snmp']:
  lines=pathlib.Path('/proc/net/'+name).read_text().splitlines()
  for a,b in zip(lines[::2],lines[1::2]):
   aa,bb=a.split(),b.split()
   if aa[0] not in ['Tcp:','TcpExt:']:continue
   for k,v in zip(aa[1:],bb[1:]):
    if any(s in k for s in ['Drop','Discard','PAWS','ACKSkipped','Checksum','InErr','RcvCollapsed','MemoryPressure','ListenOverflow','Retrans','ZeroWindow','OFO']):counts[aa[0]+k]=int(v)
 print(json.dumps({'at':now(),'counters':counts,**snapshot('jp')}),flush=True)
 if i<11:time.sleep(5)
